const CLOSERS = { ')': '(', ']': '[', '}': '{' };

export function isBalanced(source) {
  if (typeof source !== 'string') throw new TypeError('source must be a string');
  const stack = [];
  let quote = null;
  for (let i = 0; i < source.length; i += 1) {
    const ch = source[i];
    if (quote !== null) {
      if (ch === '\\') {
        i += 1;
        continue;
      }
      if (ch === quote) quote = null;
      continue;
    }
    if (ch === "'" || ch === '"') {
      quote = ch;
      continue;
    }
    if (ch === '(' || ch === '[' || ch === '{') {
      stack.push(ch);
      continue;
    }
    if (Object.prototype.hasOwnProperty.call(CLOSERS, ch)) {
      if (stack.pop() !== CLOSERS[ch]) return false;
    }
  }
  return quote === null && stack.length === 0;
}
